    $worksheet = $workbook->getActiveSheet();
    $worksheet->getCell('A2')->setValue('A2');
    $worksheet->getCell('C1')->setValue('C1');
    $worksheet->removeRow(1);
    self::assertEquals(
        'A2',
        $worksheet->getCell('A1')->getValue()
    );
    self::assertNull(
